import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Vendors — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Vendors — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/vendors"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Vendors — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/vendors"}]]},"headers":[],"relativePath":"user-guide/vendors.md","filePath":"user-guide/vendors.md","lastUpdated":1787351200000}'),n={name:"user-guide/vendors.md"};function s(i,e,d,l,c,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="vendors-—-user-guide" tabindex="-1">Vendors — User Guide <a class="header-anchor" href="#vendors-—-user-guide" aria-label="Permalink to &quot;Vendors — User Guide&quot;">​</a></h1><h2 id="who-can-use-vendors" tabindex="-1">Who can use Vendors <a class="header-anchor" href="#who-can-use-vendors" aria-label="Permalink to &quot;Who can use Vendors&quot;">​</a></h2><p>Your workspace must have the <strong>Vendors</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code> as needed).</p><p>Without <strong>assign</strong>, you only see vendors assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Vendors</strong> from the sidebar, under the <strong>Purchasing</strong> group.</p><ul><li>Search by name, email, phone, website, address, or tax ID</li><li>Filter by status (Active / Inactive) and assignee, or toggle <strong>My Vendors</strong></li><li>KPI cards summarize total vendors, my vendors, unassigned, active, and inactive</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted vendor from the row menu</li><li><strong>Delete permanently</strong> (force delete) requires <code>vendors.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New vendor</strong></li><li>Enter name (required) and optional email, phone, website, address, tax ID, payment terms, currency, status, and assignee</li><li>Save</li></ol><p>Edit from the row menu or the vendor record page.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the vendor record page or the create/edit form.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the vendor</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, and delete/restore events</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Vendors have a <strong>status</strong> of Active or Inactive (default Active). Inactive vendors remain in the directory but signal they are not currently used for procurement.</p>',16)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
